export const TRADE_TEXTS: Table = {
  "Stiff with salt and patched with sailcloth. It always knows which way the wind blows.": ["Sztywna od soli i łatana płótnem żaglowym. Zawsze wie, skąd wieje wiatr.", "Dura de sal e remendada com lona de vela. Sempre sabe de onde sopra o vento."],
  "Board your own boat at a mooring by a pier and sail the open sea: every tile teaches sailing, a voyage to another harbour pays a bonus, and out at sea you can salvage wreckage and fish from the boat.": ["Wsiądź do własnej łodzi przy palu cumowniczym obok pomostu i żegluj po otwartym morzu: każde pole uczy żeglarstwa, rejs do innego portu daje premię, a na morzu możesz wyławiać szczątki i łowić ryby z łodzi.", "Embarque no seu próprio barco num poste de amarração junto ao píer e navegue em mar aberto: cada quadrado ensina navegação, uma viagem a outro porto dá um bônus, e no mar você pode recolher destroços e pescar do barco."],
  "Buy a boat from me and keep the deed in your pack. At any harbour or island landing there are mooring posts beside the pier: use one and you are afloat. Sail over the water as you would walk, and come ashore at any mooring. Every tile sailed teaches you something, and a long voyage to another harbour teaches you a great deal. Out on the open sea you can haul in floating wreckage and fish from the boat. Watch the sky, and watch the water.": [
    "Kup u mnie łódź i trzymaj akt własności w plecaku. W każdym porcie i przystani na wyspie są pale cumownicze przy pomoście: użyj jednego, a jesteś na wodzie. Żegluj po wodzie tak, jak chodzisz, i schodź na ląd przy dowolnym palu. Każde przepłynięte pole czegoś uczy, a długi rejs do innego portu uczy bardzo wiele. Na otwartym morzu możesz wyławiać dryfujące szczątki i łowić ryby z łodzi. Patrz w niebo i patrz w wodę.",
    "Compre um barco comigo e guarde a escritura na mochila. Em cada porto ou desembarcadouro de ilha há postes de amarração junto ao píer: use um e você está na água. Navegue pela água como se andasse e desembarque em qualquer amarração. Cada quadrado navegado ensina algo, e uma longa viagem a outro porto ensina muito. Em mar aberto você pode recolher destroços à deriva e pescar do barco. Olhe o céu e olhe a água.",
  ],
  "Worn while on a slayer task: 8% more damage to the monsters of your task.": ["Noszony podczas zadania łowcy: 8% więcej obrażeń przeciw potworom z zadania.", "Usado durante uma tarefa de caça: 8% mais dano contra os monstros da tarefa."],
  "Thick wool that muffles every sound. With it on, a slayer can hurt the wailing shades.": ["Gruba wełna tłumiąca każdy dźwięk. W nim łowca może zranić zawodzące cienie.", "Lã grossa que abafa todo som. Com ele, um caçador pode ferir as sombras uivantes."],
  "There is always a little soil in its hem, and it smells of rain.": ["W jej obrąbku zawsze jest trochę ziemi i pachnie deszczem.", "Sempre há um pouco de terra na barra, e ela cheira a chuva."],
  "Patched with the pelts of a hundred careful catches.": ["Połatana skórami ze stu ostrożnych połowów.", "Remendada com as peles de cem capturas cuidadosas."],
  "Each stitch marks a task done. There are a great many stitches.": ["Każdy ścieg to wykonane zadanie. Ściegów jest bardzo wiele.", "Cada ponto marca uma tarefa cumprida. Há muitíssimos pontos."],
  "Plant seeds in farm patches with a trowel; they grow in real time, even while you are away. Harvest vegetables and herbs.": ["Sadź nasiona łopatką na grządkach; rosną w prawdziwym czasie, nawet gdy cię nie ma. Zbieraj warzywa i zioła.", "Plante sementes nos canteiros com uma colher de jardinagem; elas crescem em tempo real, mesmo quando você está fora. Colha legumes e ervas."],
  "Set box traps by burrows and snares in nesting bushes, then collect what you catch: pelts, plumes, feathers and pet morsels.": ["Rozstawiaj pułapki skrzynkowe przy norach i sidła w krzakach z gniazdami, potem zbieraj połów: skóry, pióra i przysmaki dla zwierzaków.", "Arme armadilhas de caixa junto às tocas e laços nos arbustos com ninhos, depois recolha o que pegar: peles, plumas, penas e petiscos para mascote."],
  "Take a task from a slayer master and slay that kind of monster for slayer experience and points. Some monsters only a slayer can hurt.": ["Weź zadanie od mistrza łowców i zabijaj ten rodzaj potworów dla doświadczenia i punktów łowcy. Niektóre potwory zrani tylko łowca.", "Pegue uma tarefa com um mestre caçador e mate esse tipo de monstro por experiência e pontos de caçador. Alguns monstros só um caçador consegue ferir."],
  "How is my task going?": ["Jak idzie moje zadanie?", "Como vai minha tarefa?"],
  "I need a slayer task.": ["Potrzebuję zadania łowcy.", "Preciso de uma tarefa de caça."],
  "Every farm has patches: allotments for vegetables and herb patches for herbs. Plant a seed with a trowel and it grows in real time — come back in a while, even after a night away, and it will be waiting. A bucket of compost on a growing patch gives a bigger harvest. Each patch is yours alone: nobody can pick what you planted. Better seeds want a higher farming level.": [
    "Każde gospodarstwo ma grządki: warzywne na warzywa i grządki ziół na zioła. Posadź nasiono łopatką, a urośnie w prawdziwym czasie — wróć po chwili, nawet po nocy, a będzie czekać. Wiadro kompostu na rosnącej grządce daje większe plony. Każda grządka jest tylko twoja: nikt nie zerwie tego, co posadziłeś. Lepsze nasiona wymagają wyższego poziomu rolnictwa.",
    "Toda fazenda tem canteiros: hortas para legumes e canteiros de ervas para ervas. Plante uma semente com a colher de jardinagem e ela cresce em tempo real — volte daqui a pouco, mesmo depois de uma noite fora, e ela estará esperando. Um balde de adubo num canteiro em crescimento dá uma colheita maior. Cada canteiro é só seu: ninguém pode colher o que você plantou. Sementes melhores pedem um nível maior de agricultura.",
  ],
  "The farm south of the plaza has patches anyone may use. Bring a trowel and a seed, plant it, and come back when it is ripe. Potatoes are quickest. Herb seeds grow herbs for potions.": [
    "Gospodarstwo na południe od placu ma grządki dla każdego. Przynieś łopatkę i nasiono, posadź je i wróć, gdy dojrzeje. Ziemniaki rosną najszybciej. Z nasion ziół rosną zioła na mikstury.",
    "A fazenda ao sul da praça tem canteiros que qualquer um pode usar. Traga uma colher de jardinagem e uma semente, plante e volte quando estiver maduro. Batatas são as mais rápidas. Sementes de ervas dão ervas para poções.",
  ],
  "Look for burrows and nesting bushes out in the wild. Set a box trap beside a burrow or a snare in a bush, then step back and wait: every few seconds something may walk in. Collect your catch for pelts, plumes and feathers, and the odd morsel your pet will love. You can look after one trap more every twenty levels, and traps you walk away from collapse back into your pack.": [
    "Szukaj nor i krzaków z gniazdami w dziczy. Rozstaw pułapkę skrzynkową przy norze albo sidło w krzaku, potem odsuń się i czekaj: co kilka sekund coś może wpaść. Zbieraj połów: skóry, pióra i od czasu do czasu przysmak, który pokocha twój zwierzak. Co dwadzieścia poziomów możesz pilnować o jedną pułapkę więcej, a pułapki, od których odejdziesz, składają się z powrotem do plecaka.",
    "Procure tocas e arbustos com ninhos na natureza. Arme uma armadilha de caixa ao lado de uma toca ou um laço num arbusto, depois afaste-se e espere: a cada poucos segundos algo pode cair. Recolha peles, plumas e penas, e de vez em quando um petisco que sua mascote vai adorar. A cada vinte níveis você cuida de uma armadilha a mais, e as armadilhas que você deixa para trás voltam desmontadas para a mochila.",
  ],
  "Ask me for a task and I will name a kind of monster and how many. Every one you slay on task teaches you slayer; finish the task for slayer points, and spend them on rewards. Some monsters only a slayer can hurt. When you outgrow me, go to Old Harrow in Highmoor, then Sister Morwen in Aurelion, then Kaelos in Valdrheim.": [
    "Poproś mnie o zadanie, a wskażę rodzaj potwora i ile ich zabić. Każdy zabity w ramach zadania uczy cię łowiectwa potworów; za ukończenie dostaniesz punkty łowcy do wydania na nagrody. Niektóre potwory zrani tylko łowca. Gdy mnie przerośniesz, idź do Starego Harrowa w Highmoor, potem do Siostry Morwen w Aurelion, potem do Kaelosa w Valdrheim.",
    "Peça-me uma tarefa e eu direi um tipo de monstro e quantos. Cada um que você matar na tarefa ensina caça a monstros; termine a tarefa para ganhar pontos de caçador e gaste-os em recompensas. Alguns monstros só um caçador consegue ferir. Quando me superar, vá ao Velho Harrow em Highmoor, depois à Irmã Morwen em Aurelion, depois a Kaelos em Valdrheim.",
  ],
  "My tasks are for level 30 and up. The wailing shades in the catacombs drown out every blow with their wail — you need slayer level 35 and a hush cowl to hurt them. I sell the cowls.": [
    "Moje zadania są od poziomu 30. Zawodzące cienie w katakumbach zagłuszają każdy cios swoim zawodzeniem — potrzebujesz poziomu łowcy 35 i kaptura ciszy, aby je zranić. Sprzedaję te kaptury.",
    "Minhas tarefas são do nível 30 para cima. As sombras uivantes nas catacumbas abafam cada golpe com seu lamento — você precisa de caçador nível 35 e de um capuz do silêncio para feri-las. Eu vendo os capuzes.",
  ],
  "I give tasks to slayers of level 60 and slayer 30. Cinder wraiths in the burning catacombs need slayer 55, marrow gargoyles slayer 70.": [
    "Daję zadania łowcom od poziomu 60 i łowcy 30. Popielne zjawy w płonących katakumbach wymagają łowcy 55, szpikowe gargulki łowcy 70.",
    "Dou tarefas a caçadores de nível 60 e caçador 30. Os espectros de cinzas nas catacumbas em chamas pedem caçador 55, as gárgulas de tutano caçador 70.",
  ],
  "Only the strongest get my tasks: level 100 and slayer 60. The abyssal horrors below the crypt answer to slayer 85 and nothing less.": [
    "Moje zadania dostają tylko najsilniejsi: poziom 100 i łowca 60. Otchłanne grozy pod kryptą ulegają tylko łowcy 85 i nikomu słabszemu.",
    "Só os mais fortes recebem minhas tarefas: nível 100 e caçador 60. Os horrores abissais sob a cripta só obedecem a caçador 85, nada menos.",
  ],
  // cape notes
  "Light as a breath of wind. It never snags on a branch.": ["Lekka jak powiew wiatru. Nigdy nie zaczepia o gałąź.", "Leve como um sopro de vento. Nunca se prende num galho."],
  "Its pockets smell of a hundred herbs at once.": ["Jej kieszenie pachną setką ziół naraz.", "Seus bolsos cheiram a cem ervas ao mesmo tempo."],
  "Somehow, nobody ever remembers seeing it.": ["Jakimś cudem nikt nigdy nie pamięta, że ją widział.", "Por algum motivo, ninguém nunca se lembra de tê-la visto."],
  // item notes
  "A small glass vial for brewing potions. Magic shops sell them.": ["Mała szklana fiolka do warzenia mikstur. Sprzedają je sklepy magiczne.", "Um pequeno frasco de vidro para preparar poções. As lojas de magia vendem."],
  "Use it to open the Herblore window: clean herbs and brew potions.": ["Użyj go, aby otworzyć okno zielarstwa: czyść zioła i warz mikstury.", "Use para abrir a janela de herbalismo: limpe ervas e prepare poções."],
  "Restores 50 running stamina.": ["Przywraca 50 punktów kondycji do biegu.", "Restaura 50 de fôlego para correr."],
  "Picks the lock of a strongbox. Sometimes it snaps.": ["Otwiera zamek skrzyni. Czasem się łamie.", "Abre a fechadura de um cofre. Às vezes se quebra."],
  "Fine silk from a merchant's stall. Traders buy it, no questions asked.": ["Delikatny jedwab ze straganu kupca. Handlarze kupią go bez pytań.", "Seda fina da barraca de um mercador. Os comerciantes compram sem perguntas."],
  "Saffron, pepper and cinnamon from the south. Worth a lot to the right buyer.": ["Szafran, pieprz i cynamon z południa. Dla właściwego kupca warte majątek.", "Açafrão, pimenta e canela do sul. Valem muito para o comprador certo."],
  "A small silver brooch. Bankers and fences buy it.": ["Mała srebrna brosza. Kupują ją bankierzy i paserzy.", "Um pequeno broche de prata. Banqueiros e receptadores compram."],
  "For planting seeds in farm patches.": ["Do sadzenia nasion na grządkach.", "Para plantar sementes nos canteiros."],
  "Use it on a growing patch: it gives a bigger harvest.": ["Użyj go na rosnącej grządce: da większe plony.", "Use num canteiro em crescimento: dá uma colheita maior."],
  "Set it beside a burrow to catch the creature inside.": ["Rozstaw ją przy norze, aby złapać jej mieszkańca.", "Arme ao lado de uma toca para pegar a criatura lá dentro."],
  "Set it in a nesting bush to catch a bird.": ["Zastaw je w krzaku z gniazdem, aby złapać ptaka.", "Arme num arbusto com ninho para pegar um pássaro."],
  "Soft grey-brown fur. Tanners turn it into leather.": ["Miękkie szarobrązowe futro. Garbarze robią z niego skórę.", "Pelo macio cinza-acastanhado. Os curtidores o transformam em couro."],
  "Smoky fur from the ash fields. Tanners pay for it.": ["Dymne futro z popielnych pól. Garbarze za nie płacą.", "Pelo esfumaçado dos campos de cinza. Os curtidores pagam por ele."],
  "Tough, sandy scales. Tanners turn it into leather.": ["Twarde, piaskowe łuski. Garbarze robią z nich skórę.", "Escamas duras cor de areia. Os curtidores as transformam em couro."],
  "White winter fur, warm as a hearth.": ["Białe zimowe futro, ciepłe jak palenisko.", "Pelo branco de inverno, quente como uma lareira."],
  "Fur the colour of embers, warm to the touch.": ["Futro barwy żaru, ciepłe w dotyku.", "Pelo da cor das brasas, quente ao toque."],
  "A long sunbird tail feather. Fletchers and tailors love it.": ["Długie pióro z ogona ptaka słonecznego. Uwielbiają je łucznicy i krawcy.", "Uma longa pena da cauda do pássaro-solar. Flecheiros e alfaiates adoram."],
  "Plucked and ready for the fire.": ["Oskubany i gotowy na ogień.", "Depenada e pronta para o fogo."],
  "A tasty bite for a pet. Use it while your pet is out: it learns a little.": ["Smaczny kąsek dla zwierzaka. Użyj go, gdy zwierzak jest przy tobie: trochę się nauczy.", "Um petisco gostoso para mascote. Use com a mascote fora: ela aprende um pouco."],
  "Your own little boat (sailing 1). Use a mooring at a dock to board it.": ["Twoja własna łódeczka (żeglarstwo 1). Użyj cumy przy pomoście, aby do niej wsiąść.", "Seu próprio barquinho (navegação 1). Use uma amarração num cais para embarcar."],
  "A one-mast sloop, quicker than a skiff (sailing 30).": ["Jednomasztowy slup, szybszy od łódki (żeglarstwo 30).", "Uma chalupa de um mastro, mais rápida que um bote (navegação 30)."],
  "A fast two-mast cutter (sailing 60).": ["Szybki dwumasztowy kuter (żeglarstwo 60).", "Um cúter veloz de dois mastros (navegação 60)."],
  // skills (tooltips) and the Herblore window
  "Pick wild herbs, clean them and brew potions with a pestle and mortar and empty vials.": ["Zbieraj dzikie zioła, czyść je i warz mikstury w moździerzu z pustymi fiolkami.", "Colha ervas silvestres, limpe-as e prepare poções com pilão e almofariz e frascos vazios."],
  "Cross shortcuts across the world: balance logs, climbing rocks, swims and squeezes. Agility also gives you more running stamina.": ["Korzystaj ze skrótów w świecie: kłód nad rzeką, skał do wspinaczki, przepraw wpław i szczelin. Zręczność daje też więcej kondycji do biegu.", "Use atalhos pelo mundo: troncos de equilíbrio, rochas de escalada, travessias a nado e fendas. A agilidade também dá mais fôlego para correr."],
  "Pick the pockets of townsfolk, steal from market stalls and pick the locks of strongboxes. Get caught and you are stunned.": ["Okradaj kieszenie mieszczan, kradnij ze straganów i otwieraj zamki skrzyń. Gdy cię złapią, zostaniesz ogłuszony.", "Bata carteiras de moradores, furte de barracas e abra fechaduras de cofres. Se for pego, fica atordoado."],
  "Clean grimy herbs, then brew a herb with an empty vial (and a monster part for the stronger brews). Brewing needs a pestle and mortar.": ["Czyść brudne zioła, potem warz zioło z pustą fiolką (do mocniejszych wywarów potrzeba jeszcze części potwora). Warzenie wymaga moździerza.", "Limpe ervas sujas e depois prepare uma erva com um frasco vazio (e uma parte de monstro para as poções mais fortes). Preparar exige pilão e almofariz."],
  "Herblore": ["Zielarstwo", "Herbalismo"],
  "How do I train?": ["Jak mam trenować?", "Como eu treino?"],
  "Agility is learned on the shortcuts of the realm: logs over rivers, rocks up the cliffs, a swim across a lake, a crack in a cave wall. Each one asks for a level; the map shows them all. Cross them again and again to learn. A higher agility level also lets you run for longer: switch running on under your stamina bar. A Draught of Vigour gives your breath back.": [
    "Zręczności uczy się na skrótach krainy: kłodach nad rzekami, skałach na urwiskach, przeprawach przez jeziora, szczelinach w ścianach jaskiń. Każdy wymaga poziomu; mapa pokazuje je wszystkie. Pokonuj je raz po raz, a nauczysz się. Wyższy poziom zręczności pozwala też dłużej biec: włącz bieg pod paskiem kondycji. Napój wigoru przywraca oddech.",
    "A agilidade se aprende nos atalhos do reino: troncos sobre rios, rochas nos penhascos, uma travessia a nado num lago, uma fenda na parede de uma caverna. Cada um pede um nível; o mapa mostra todos. Atravesse-os de novo e de novo para aprender. Um nível maior de agilidade também deixa você correr por mais tempo: ligue a corrida sob a barra de fôlego. Uma Poção de vigor devolve o fôlego.",
  ],
  "Start with the farmhands: their pockets are easy and their slaps are soft. Then the market stalls — but never with the keeper watching you. The strongboxes in bandit camps and old ruins need a lockpick, and their traps bite. If you are caught you are stunned for a moment, so do not try it next to anything that can hit back. And never, ever another adventurer: the realm will not allow it. I buy what you bring, no questions.": [
    "Zacznij od parobków: ich kieszenie są łatwe, a policzki miękkie. Potem stragany — ale nigdy, gdy kupiec na ciebie patrzy. Skrzynie w obozach bandytów i starych ruinach wymagają wytrycha, a ich pułapki gryzą. Jeśli cię złapią, będziesz przez chwilę ogłuszony, więc nie próbuj tego obok czegoś, co może oddać. I nigdy, przenigdy innego poszukiwacza przygód: kraina na to nie pozwoli. Kupię wszystko, co przyniesiesz, bez pytań.",
    "Comece pelos lavradores: os bolsos são fáceis e os tapas são fracos. Depois as barracas do mercado — mas nunca com o dono olhando. Os cofres nos acampamentos de bandidos e nas ruínas antigas pedem uma gazua, e suas armadilhas mordem. Se for pego, fica atordoado por um instante, então não tente ao lado de algo que possa revidar. E nunca, jamais, outro aventureiro: o reino não permite. Eu compro o que você trouxer, sem perguntas.",
  ],
  "Wild herbs grow all over the realm: marshwort in the meadows, frostmint in the snow, sunpetal in the deserts, starbloom only in the wildest places. They come up grimy; clean them with a pestle and mortar, then brew one with an empty vial. The stronger brews want a monster part as well — a bear paw, a scorpion tail. You can grow herbs in a herb patch too, once you know a little farming.": [
    "Dzikie zioła rosną w całej krainie: bagiennik na łąkach, mroźna mięta w śniegu, słoneczny płatek na pustyniach, gwiezdny kwiat tylko w najdzikszych miejscach. Zbierasz je brudne; oczyść je w moździerzu, potem uwarz jedno z pustą fiolką. Mocniejsze wywary wymagają też części potwora — niedźwiedziej łapy, ogona skorpiona. Zioła możesz też uprawiać na grządce ziół, gdy poznasz trochę rolnictwa.",
    "Ervas silvestres crescem por todo o reino: erva-do-brejo nos prados, menta-gélida na neve, pétala-solar nos desertos, flor-estelar só nos lugares mais selvagens. Elas vêm sujas; limpe-as com pilão e almofariz e depois prepare uma com um frasco vazio. As poções mais fortes também pedem uma parte de monstro — uma pata de urso, uma cauda de escorpião. Você também pode cultivar ervas num canteiro de ervas, quando souber um pouco de agricultura.",
  ],
};

export const TRADE_MESSAGES: Table = {
  "You need a boat to sail from here. Captain Maren Tallow, the shipwright in Millbrook, sells them.": ["Aby stąd wypłynąć, potrzebujesz łodzi. Sprzedaje je kapitan Maren Tallow, szkutniczka w Millbrook.", "Você precisa de um barco para zarpar daqui. A capitã Maren Tallow, construtora naval em Millbrook, vende."],
  "You need sailing level {level} to sail that boat.": ["Potrzebujesz poziomu żeglarstwa {level}, aby pływać tą łodzią.", "Você precisa de navegação nível {level} para navegar esse barco."],
  "You need sailing level {level} to haul in this wreckage.": ["Potrzebujesz poziomu żeglarstwa {level}, aby wyłowić te szczątki.", "Você precisa de navegação nível {level} para recolher esses destroços."],
  "Mind the tar, {name}. Every boat on this coast went through my hands.": ["Uważaj na smołę, {name}. Każda łódź na tym wybrzeżu przeszła przez moje ręce.", "Cuidado com o piche, {name}. Todo barco desta costa passou pelas minhas mãos."],
  "You cannot light a fire in a boat.": ["Nie możesz rozpalić ogniska w łodzi.", "Você não pode acender uma fogueira num barco."],
  "Someone is standing on the pier.": ["Ktoś stoi na pomoście.", "Há alguém de pé no píer."],
  "Another boat is tied up there.": ["Przycumowana jest tam już inna łódź.", "Outro barco está amarrado ali."],
  "You climb into your {name} and cast off. Sail anywhere over water; come ashore at any mooring.": ["Wsiadasz do łodzi ({name}) i odbijasz od brzegu. Żegluj gdziekolwiek po wodzie; zejdziesz na ląd przy dowolnym palu cumowniczym.", "Você entra no seu barco ({name}) e zarpa. Navegue por onde houver água; desembarque em qualquer amarração."],
  "You tie up at {name}. A voyage of {dist} tiles from {name2}: {xp} sailing experience.": ["Cumujesz w: {name}. Rejs na {dist} pól z: {name2} — doświadczenie żeglarskie: {xp}.", "Você atraca em {name}. Uma viagem de {dist} quadrados desde {name2}: {xp} de experiência de navegação."],
  "You tie up at {name} and step ashore.": ["Cumujesz w: {name} i schodzisz na ląd.", "Você atraca em {name} e desembarca."],
  "You tie up your boat and step ashore.": ["Cumujesz łódź i schodzisz na ląd.", "Você amarra o barco e desembarca."],
  "A crate drifts past and you haul it aboard: {got}.": ["Obok dryfuje skrzynia, wciągasz ją na pokład: {got}.", "Um caixote passa à deriva e você o puxa a bordo: {got}."],
  "A sudden squall slams into your boat!": ["Nagły szkwał uderza w twoją łódź!", "Uma rajada súbita atinge o seu barco!"],
  "The squall throws you against the side of the boat.": ["Szkwał rzuca tobą o burtę łodzi.", "A rajada joga você contra o costado do barco."],
  "Something rises out of the deep: a {name}!": ["Coś wynurza się z głębin: {name}!", "Algo sobe das profundezas: {name}!"],
  "Only a few splinters are left. The sea will bring more.": ["Zostało tylko kilka drzazg. Morze przyniesie więcej.", "Só restam algumas lascas. O mar trará mais."],
  "The wreckage floats out of reach. You need a boat.": ["Szczątki dryfują poza zasięgiem. Potrzebujesz łodzi.", "Os destroços flutuam fora de alcance. Você precisa de um barco."],
  "You lean over the side and reach for the wreckage...": ["Wychylasz się za burtę i sięgasz po szczątki...", "Você se debruça na borda e estica a mão para os destroços..."],
  "The wreckage bobs away from your hands. Try again.": ["Szczątki wymykają ci się z rąk. Spróbuj jeszcze raz.", "Os destroços escapam das suas mãos. Tente de novo."],
  "You salvage {got}.": ["Wyławiasz: {got}.", "Você recupera: {got}."],
  "You cannot do that from a boat. Come ashore at a mooring first.": ["Nie możesz tego zrobić z łodzi. Najpierw zejdź na ląd przy palu cumowniczym.", "Você não pode fazer isso de um barco. Desembarque numa amarração primeiro."],
  "Wipe your boots, {name}. Good soil is a thing to be respected.": ["Wytrzyj buty, {name}. Dobrą ziemię trzeba szanować.", "Limpe as botas, {name}. Terra boa merece respeito."],
  "Seeds, {name}! Potatoes for the hungry, herbs for the clever.": ["Nasiona, {name}! Ziemniaki dla głodnych, zioła dla mądrych.", "Sementes, {name}! Batatas para os famintos, ervas para os espertos."],
  "Quiet, {name}. You are standing on a hare run.": ["Cicho, {name}. Stoisz na zajęczej ścieżce.", "Silêncio, {name}. Você está pisando numa trilha de lebres."],
  "Another one who wants to hunt for a living, {name}? Good. The realm has plenty that needs killing.": ["Kolejny, kto chce żyć z polowania, {name}? Dobrze. W krainie nie brakuje tego, co trzeba ubić.", "Mais um que quer viver de caçar, {name}? Ótimo. O reino tem muito que precisa ser morto."],
  "Thirty years of tasks, {name}, and I still have all my fingers. Mostly.": ["Trzydzieści lat zadań, {name}, a wciąż mam wszystkie palce. Prawie.", "Trinta anos de tarefas, {name}, e ainda tenho todos os dedos. Quase."],
  "Kneel if you like, {name}. Then stand up and fight something.": ["Uklęknij, jeśli chcesz, {name}. Potem wstań i z czymś walcz.", "Ajoelhe-se se quiser, {name}. Depois levante-se e lute com alguma coisa."],
  "Speak quickly, {name}. Something is always waking up somewhere.": ["Mów szybko, {name}. Gdzieś zawsze coś się budzi.", "Fale depressa, {name}. Sempre há algo despertando em algum lugar."],
  "Call your pet first, then give it the morsel.": ["Najpierw przywołaj zwierzaka, potem daj mu przysmak.", "Chame sua mascote primeiro, depois dê o petisco."],
  "Your pet gobbles the morsel down happily.": ["Twój zwierzak radośnie pałaszuje przysmak.", "Sua mascote devora o petisco toda feliz."],
  "Use a farm patch to plant your seeds (with a trowel in your pack) or to put compost on what grows there.": ["Użyj grządki, aby posadzić nasiona (z łopatką w plecaku) albo posypać kompostem to, co na niej rośnie.", "Use um canteiro para plantar suas sementes (com uma colher de jardinagem na mochila) ou pôr adubo no que cresce ali."],
  "Use a burrow to set a box trap beside it.": ["Użyj nory, aby rozstawić przy niej pułapkę skrzynkową.", "Use uma toca para armar uma armadilha de caixa ao lado."],
  "Use a nesting bush to set a bird snare in it.": ["Użyj krzaka z gniazdem, aby zastawić w nim sidło.", "Use um arbusto com ninho para armar um laço nele."],
  "This herb patch is empty. Plant a herb seed here with a trowel.": ["Ta grządka ziół jest pusta. Posadź tu łopatką nasiono zioła.", "Este canteiro de ervas está vazio. Plante aqui uma semente de erva com a colher de jardinagem."],
  "This allotment is empty. Plant vegetable seeds here with a trowel.": ["Ta grządka warzywna jest pusta. Posadź tu łopatką nasiona warzyw.", "Esta horta está vazia. Plante aqui sementes de legumes com a colher de jardinagem."],
  "You need farming level {level} to plant those seeds.": ["Potrzebujesz poziomu rolnictwa {level}, aby posadzić te nasiona.", "Você precisa de agricultura nível {level} para plantar essas sementes."],
  "You need a gardening trowel to plant. Farmers and seed sellers have them.": ["Do sadzenia potrzebujesz ogrodniczej łopatki. Mają je rolnicy i sprzedawcy nasion.", "Você precisa de uma colher de jardinagem para plantar. Fazendeiros e vendedores de sementes têm."],
  "Your herb is growing ({name}). Ready in about {left} minutes.": ["Twoje zioło rośnie ({name}). Będzie gotowe za około {left} min.", "Sua erva está crescendo ({name}). Pronta em cerca de {left} minutos."],
  "Your crop is growing ({name}). Ready in about {left} minutes.": ["Twoja uprawa rośnie ({name}). Będzie gotowa za około {left} min.", "Sua plantação está crescendo ({name}). Pronta em cerca de {left} minutos."],
  "You plant {name} in the {kind}. Ripe in about {minutes} minutes, even while you are away.": ["Sadzisz: {name} ({kind}). Dojrzeje za około {minutes} min, nawet gdy cię nie będzie.", "Você planta {name} ({kind}). Fica maduro em cerca de {minutes} minutos, mesmo quando você estiver fora."],
  "You spread compost over your {name}. The harvest will be bigger.": ["Rozsypujesz kompost na uprawie ({name}). Plony będą większe.", "Você espalha adubo sobre {name}. A colheita será maior."],
  "You harvest {got}.": ["Zbierasz: {got}.", "Você colhe: {got}."],
  "Nothing here would walk into a trap of yours yet. You need hunter level {lowest}.": ["Nic tutaj nie wpadnie jeszcze w twoją pułapkę. Potrzebujesz poziomu łowiectwa {lowest}.", "Nada aqui cairia numa armadilha sua ainda. Você precisa de caça nível {lowest}."],
  "All your traps of that kind are set already.": ["Wszystkie twoje pułapki tego rodzaju są już rozstawione.", "Todas as suas armadilhas desse tipo já estão armadas."],
  "You need a box trap to set here. Huntmaster Ketta in Briarwatch sells them.": ["Potrzebujesz tu pułapki skrzynkowej. Sprzedaje je łowczyni Ketta w Briarwatch.", "Você precisa de uma armadilha de caixa aqui. A mestra-caçadora Ketta, em Briarwatch, vende."],
  "You need a bird snare to set here. Huntmaster Ketta in Briarwatch sells them.": ["Potrzebujesz tu sidła na ptaki. Sprzedaje je łowczyni Ketta w Briarwatch.", "Você precisa de um laço para pássaros aqui. A mestra-caçadora Ketta, em Briarwatch, vende."],
  "You can only look after {lvl} traps at your hunter level.": ["Na twoim poziomie łowiectwa możesz pilnować tylko tylu pułapek: {lvl}.", "No seu nível de caça você só consegue cuidar de {lvl} armadilhas."],
  "You take your trap back.": ["Zabierasz swoją pułapkę.", "Você pega sua armadilha de volta."],
  "You set a box trap beside the burrow. Step back and wait.": ["Rozstawiasz pułapkę skrzynkową przy norze. Odsuń się i czekaj.", "Você arma uma armadilha de caixa ao lado da toca. Afaste-se e espere."],
  "You set a snare in the nesting bush. Step back and wait.": ["Zastawiasz sidło w krzaku z gniazdem. Odsuń się i czekaj.", "Você arma um laço no arbusto com ninho. Afaste-se e espere."],
  "You set the trap again.": ["Ponownie rozstawiasz pułapkę.", "Você arma a armadilha de novo."],
  "You take the {name} out of the trap: {got}.": ["Wyjmujesz z pułapki: {name} — {got}.", "Você tira {name} da armadilha: {got}."],
  "nothing worth keeping": ["nic wartego zachowania", "nada que valha guardar"],
  "You leave a trap behind and it collapses. You gather it up as you go.": ["Zostawiasz pułapkę i ta się składa. Zabierasz ją po drodze.", "Você deixa uma armadilha para trás e ela se desmonta. Você a recolhe no caminho."],
  "One of your traps has been sprung empty. Set it again.": ["Jedna z twoich pułapek zatrzasnęła się pusta. Rozstaw ją ponownie.", "Uma das suas armadilhas disparou vazia. Arme-a de novo."],
  "Something is in one of your traps: {name}!": ["W jednej z twoich pułapek coś jest: {name}!", "Há algo numa das suas armadilhas: {name}!"],
  "Slayer task: {left} {name} left.": ["Zadanie łowcy: pozostało {left} ({name}).", "Tarefa de caça: faltam {left} ({name})."],
  "Slayer task complete! You earn {pts} slayer points ({points} in all, {streak} tasks in a row). Any slayer master has a new task for you.": ["Zadanie łowcy wykonane! Zdobywasz punkty łowcy: {pts} (razem {points}, zadań z rzędu: {streak}). Każdy mistrz łowców ma dla ciebie nowe zadanie.", "Tarefa de caça concluída! Você ganha {pts} pontos de caçador ({points} no total, {streak} tarefas seguidas). Qualquer mestre caçador tem uma nova tarefa para você."],
  "Slayer rewards ({points} points).": ["Nagrody łowcy (punkty: {points}).", "Recompensas de caçador ({points} pontos)."],
  "{label} — {cost} points": ["{label} — punkty: {cost}", "{label} — {cost} pontos"],
  "You are not ready for my work yet. Come back at level {minLevel}.": ["Nie jesteś jeszcze gotów na moją robotę. Wróć na poziomie {minLevel}.", "Você ainda não está pronto para o meu trabalho. Volte no nível {minLevel}."],
  "My tasks are for seasoned slayers. Come back with slayer level {minSlayer}.": ["Moje zadania są dla doświadczonych łowców. Wróć z poziomem łowcy {minSlayer}.", "Minhas tarefas são para caçadores experientes. Volte com caçador nível {minSlayer}."],
  "I have nothing for you right now.": ["Nie mam teraz nic dla ciebie.", "Não tenho nada para você agora."],
  "New slayer task: slay {n} {name}.": ["Nowe zadanie łowcy: zabij {n} ({name}).", "Nova tarefa de caça: mate {n} ({name})."],
  "Your task: slay {n} {name}. Any slayer master will give you the next one when you are done.": ["Twoje zadanie: zabij {n} ({name}). Każdy mistrz łowców da ci kolejne, gdy skończysz.", "Sua tarefa: mate {n} ({name}). Qualquer mestre caçador lhe dará a próxima quando terminar."],
  "You still have {left} of {total} {name} to slay.": ["Zostało ci do zabicia {left} z {total} ({name}).", "Você ainda tem {left} de {total} ({name}) para matar."],
  "You have {points} slayer points. What will it be?": ["Masz punkty łowcy: {points}. Co wybierasz?", "Você tem {points} pontos de caçador. O que vai ser?"],
  "You do not have enough points for that.": ["Nie masz na to dość punktów.", "Você não tem pontos suficientes para isso."],
  "Make some room in your backpack first.": ["Najpierw zrób miejsce w plecaku.", "Abra espaço na mochila primeiro."],
  "Done. Ask me for a new task whenever you like.": ["Załatwione. Poproś o nowe zadanie, kiedy zechcesz.", "Feito. Peça uma nova tarefa quando quiser."],
  "There you are. Use it well.": ["Proszę bardzo. Korzystaj z tego dobrze.", "Aqui está. Use bem."],
  "Its shell turns every blow aside. Only a slayer (level 10) knows where to strike.": ["Jego pancerz odbija każdy cios. Tylko łowca (poziom 10) wie, gdzie uderzyć.", "A carapaça desvia todo golpe. Só um caçador (nível 10) sabe onde acertar."],
  "Its wail drowns out every blow. You need slayer level 35 and a hush cowl on your head.": ["Jego zawodzenie zagłusza każdy cios. Potrzebujesz poziomu łowcy 35 i kaptura ciszy na głowie.", "Seu lamento abafa todo golpe. Você precisa de caçador nível 35 e de um capuz do silêncio na cabeça."],
  "Your blows pass through its embers. Only a slayer of level 55 can bind it.": ["Twoje ciosy przechodzą przez jego żar. Tylko łowca na poziomie 55 może go spętać.", "Seus golpes atravessam as brasas. Só um caçador de nível 55 consegue prendê-lo."],
  "Stone and bone, and no weak spot you can see. It takes slayer level 70.": ["Kamień i kość, i żadnego słabego punktu. Potrzeba poziomu łowcy 70.", "Pedra e osso, e nenhum ponto fraco à vista. É preciso caçador nível 70."],
  "Your weapon will not touch what came out of the abyss. It takes slayer level 85.": ["Twoja broń nie tknie tego, co wyszło z otchłani. Potrzeba poziomu łowcy 85.", "Sua arma não toca o que saiu do abismo. É preciso caçador nível 85."],
  // NPC lines
  "Light feet, {name}! The long way round is for people who never learned to climb.": ["Lekkie stopy, {name}! Okrężna droga jest dla tych, co nigdy nie nauczyli się wspinać.", "Pés leves, {name}! O caminho mais longo é para quem nunca aprendeu a escalar."],
  "Keep your hands where I can see them, {name}. Mine are always busy.": ["Trzymaj ręce tak, żebym je widział, {name}. Moje zawsze są zajęte.", "Mantenha as mãos onde eu possa vê-las, {name}. As minhas estão sempre ocupadas."],
  "Mind the drying racks, {name}. Every leaf on them is somebody's cure.": ["Uważaj na suszarnie, {name}. Każdy listek na nich to czyjeś lekarstwo.", "Cuidado com os varais de secagem, {name}. Cada folha neles é a cura de alguém."],
  "Busy day, {name}. The fields will not plough themselves.": ["Pracowity dzień, {name}. Pola same się nie zaorzą.", "Dia cheio, {name}. Os campos não se aram sozinhos."],
  "Mind the ropes, {name}. Ships to load.": ["Uważaj na liny, {name}. Statki czekają na załadunek.", "Cuidado com as cordas, {name}. Há navios para carregar."],
  "Fine goods, fair prices, {name}. Well — fair for me.": ["Dobre towary, uczciwe ceny, {name}. No — uczciwe dla mnie.", "Bons produtos, preços justos, {name}. Bem — justos para mim."],
  "Move along, {name}. Nothing to see here.": ["Idź dalej, {name}. Nie ma tu nic do oglądania.", "Circulando, {name}. Não há nada para ver aqui."],
  "Hm? Oh. Good day, {name}. I was reading.": ["Hm? Ach. Dzień dobry, {name}. Czytałem.", "Hã? Ah. Bom dia, {name}. Eu estava lendo."],
  "Do not stand so close, {name}. This cloak cost more than your house.": ["Nie stój tak blisko, {name}. Ten płaszcz kosztował więcej niż twój dom.", "Não fique tão perto, {name}. Esta capa custou mais que a sua casa."],
  "Shift starts at the bell, {name}. Are you here to dig or to talk?": ["Zmiana zaczyna się z dzwonem, {name}. Przyszedłeś kopać czy gadać?", "O turno começa com o sino, {name}. Você veio cavar ou conversar?"],
  // item notes with a level
  "Herblore {n}: clean it with a pestle and mortar (or from the Herblore window) before brewing.": ["Zielarstwo {n}: oczyść je w moździerzu (lub w oknie zielarstwa) przed warzeniem.", "Herbalismo {n}: limpe com pilão e almofariz (ou na janela de herbalismo) antes de preparar."],
  "A clean herb. Herblore {n}: brew it with an empty vial.": ["Czyste zioło. Zielarstwo {n}: uwarz je z pustą fiolką.", "Uma erva limpa. Herbalismo {n}: prepare com um frasco vazio."],
  "A clean herb. Herblore {n}: brew it with an empty vial and one more ingredient.": ["Czyste zioło. Zielarstwo {n}: uwarz je z pustą fiolką i jeszcze jednym składnikiem.", "Uma erva limpa. Herbalismo {n}: prepare com um frasco vazio e mais um ingrediente."],
  "Grown in an allotment (farming {n}).": ["Uprawiane na grządce warzywnej (rolnictwo {n}).", "Cultivado numa horta (agricultura {n})."],
  "Farming {n}: plant it in an allotment patch with a trowel.": ["Rolnictwo {n}: posadź je łopatką na grządce warzywnej.", "Agricultura {n}: plante numa horta com uma colher de jardinagem."],
  "Farming {n}: plant it in a herb patch with a trowel.": ["Rolnictwo {n}: posadź je łopatką na grządce ziół.", "Agricultura {n}: plante num canteiro de ervas com uma colher de jardinagem."],
  "Townsfolk ({name})": ["Mieszczanin ({name})", "Morador ({name})"],
  // running and agility
  "You are out of breath and slow to a walk.": ["Brakuje ci tchu i zwalniasz do marszu.", "Você perde o fôlego e passa a andar."],
  "You start running. Running uses stamina; it comes back while you walk or rest.": ["Zaczynasz biec. Bieg zużywa kondycję; wraca ona podczas marszu i odpoczynku.", "Você começa a correr. Correr gasta fôlego; ele volta enquanto você anda ou descansa."],
  "You walk.": ["Idziesz.", "Você anda."],
  "Someone is in the way on the other side.": ["Ktoś stoi po drugiej stronie.", "Há alguém no caminho do outro lado."],
  "You need agility level {level} to use this {name}.": ["Potrzebujesz poziomu zręczności {level}, aby użyć: {name}.", "Você precisa de agilidade nível {level} para usar: {name}."],
  "You step onto the log, arms out.": ["Wchodzisz na kłodę z rozłożonymi rękami.", "Você sobe no tronco de braços abertos."],
  "You balance across the log.": ["Przechodzisz po kłodzie, łapiąc równowagę.", "Você atravessa o tronco se equilibrando."],
  "You lose your footing and fall into the water!": ["Tracisz równowagę i wpadasz do wody!", "Você perde o equilíbrio e cai na água!"],
  "You find a handhold and start to climb.": ["Znajdujesz chwyt i zaczynasz się wspinać.", "Você acha onde se segurar e começa a escalar."],
  "You climb over the rocks.": ["Wspinasz się przez skały.", "Você escala as rochas."],
  "A handhold breaks and you slide back down!": ["Chwyt się kruszy i zsuwasz się na dół!", "Um apoio se quebra e você escorrega para baixo!"],
  "You wade in and start to swim.": ["Wchodzisz do wody i zaczynasz płynąć.", "Você entra na água e começa a nadar."],
  "You swim across and climb out.": ["Przepływasz na drugą stronę i wychodzisz na brzeg.", "Você atravessa a nado e sai da água."],
  "The current drags you back to the bank!": ["Prąd znosi cię z powrotem na brzeg!", "A correnteza o arrasta de volta à margem!"],
  "You breathe out and squeeze into the crack.": ["Robisz wydech i wciskasz się w szczelinę.", "Você solta o ar e se espreme na fenda."],
  "You squeeze through the gap.": ["Przeciskasz się przez szczelinę.", "Você se espreme pela fenda."],
  "You get stuck and have to wriggle back out!": ["Utykasz i musisz się wycofać!", "Você fica entalado e precisa sair de volta!"],
  // thieving
  "The stall is bare. The keeper will put more out soon.": ["Stragan jest pusty. Kupiec niedługo wyłoży więcej.", "A barraca está vazia. O dono vai repor logo."],
  "The strongbox hangs open and empty.": ["Skrzynia stoi otwarta i pusta.", "O cofre está aberto e vazio."],
  "You need thieving level {level} to steal from a {name}.": ["Potrzebujesz poziomu złodziejstwa {level}, aby okraść: {name}.", "Você precisa de furto nível {level} para furtar de: {name}."],
  "You need thieving level {level} to pick this lock.": ["Potrzebujesz poziomu złodziejstwa {level}, aby otworzyć ten zamek.", "Você precisa de furto nível {level} para abrir esta fechadura."],
  "You need a lockpick. Sly Morwick in Corvane sells them.": ["Potrzebujesz wytrycha. Sprzedaje je Chytry Morwick w Corvane.", "Você precisa de uma gazua. Morwick, o Astuto, em Corvane, vende."],
  "You need a lockpick.": ["Potrzebujesz wytrycha.", "Você precisa de uma gazua."],
  "You need herblore level {level} to pick {name}.": ["Potrzebujesz poziomu zielarstwa {level}, aby zebrać: {name}.", "Você precisa de herbalismo nível {level} para colher: {name}."],
  "You reach for the {name}...": ["Sięgasz ku temu, co leży na: {name}...", "Você estica a mão para: {name}..."],
  "You work the lockpick into the lock...": ["Wsuwasz wytrych do zamka...", "Você enfia a gazua na fechadura..."],
  "You search the {name} for good leaves.": ["Szukasz dobrych liści: {name}.", "Você procura boas folhas: {name}."],
  "You would never get away with robbing {name}.": ["Nigdy nie uszłoby ci na sucho okradzenie: {name}.", "Você nunca escaparia impune roubando: {name}."],
  "You need thieving level {level} to pick a {name}'s pocket.": ["Potrzebujesz poziomu złodziejstwa {level}, aby okraść kieszeń (cel: {name}).", "Você precisa de furto nível {level} para bater a carteira de: {name}."],
  "You slip a hand towards {name}'s purse...": ["Wsuwasz rękę w stronę sakiewki (cel: {name})...", "Você desliza a mão até a bolsa de {name}..."],
  "You pick {name}'s pocket: {got}.": ["Okradasz kieszeń ({name}): {got}.", "Você bate a carteira de {name}: {got}."],
  "{name} catches you and gives you a clout. You are stunned!": ["{name} łapie cię i daje ci w ucho. Jesteś ogłuszony!", "{name} pega você e lhe dá um tapa. Você fica atordoado!"],
  "You snatch {got} from the {name}.": ["Porywasz {got} ({name}).", "Você surrupia {got} de: {name}."],
  "{name}: Stop, thief!": ["{name}: Stój, złodzieju!", "{name}: Pare, ladrão!"],
  "You are shoved away from the stall and stunned!": ["Ktoś odpycha cię od straganu i jesteś ogłuszony!", "Você é empurrado para longe da barraca e fica atordoado!"],
  "You fumble and knock the goods back. Nobody noticed.": ["Partaczysz i strącasz towar z powrotem. Nikt nie zauważył.", "Você se atrapalha e derruba as mercadorias de volta. Ninguém percebeu."],
  "The lock clicks open. Inside: {got}.": ["Zamek ustępuje z kliknięciem. W środku: {got}.", "A fechadura se abre com um clique. Dentro: {got}."],
  "Your lockpick snaps in the lock.": ["Twój wytrych łamie się w zamku.", "Sua gazua quebra na fechadura."],
  "A needle springs out of the lock. Poison!": ["Z zamka wyskakuje igła. Trucizna!", "Uma agulha salta da fechadura. Veneno!"],
  "The box's trap snaps at your fingers!": ["Pułapka skrzyni chwyta cię za palce!", "A armadilha do cofre morde seus dedos!"],
  "Oi! Hands off, you!": ["Hej! Łapy precz!", "Ei! Tira a mão daí!"],
  "Thief! I felt that!": ["Złodziej! Poczułem to!", "Ladrão! Eu senti isso!"],
  "Guards! A cutpurse!": ["Straże! Rzezimieszek!", "Guardas! Um batedor de carteiras!"],
  "You picked the wrong pocket, friend.": ["Wybrałeś złą kieszeń, przyjacielu.", "Você escolheu o bolso errado, amigo."],
  "Unhand my satchel!": ["Puść moją torbę!", "Solte a minha bolsa!"],
  "How dare you! Guards!": ["Jak śmiesz! Straże!", "Como ousa! Guardas!"],
  "By my beard, a thief!": ["Na moją brodę, złodziej!", "Pelas minhas barbas, um ladrão!"],
  "(Pick their pocket — thieving {level})": ["(Okradnij kieszeń — złodziejstwo {level})", "(Bater a carteira — furto {level})"],
  // herbs and the Draught of Vigour
  "You pick some {name}.": ["Zbierasz: {name}.", "Você colhe: {name}."],
  "You are not out of breath.": ["Nie brakuje ci tchu.", "Você não está sem fôlego."],
  "You feel your breath come back.": ["Czujesz, jak wraca ci oddech.", "Você sente o fôlego voltar."],
  "Use a strongbox to pick its lock. You will find them in bandit camps and old ruins.": ["Użyj skrzyni, aby otworzyć jej zamek. Znajdziesz je w obozach bandytów i starych ruinach.", "Use um cofre para abrir a fechadura. Você os encontra em acampamentos de bandidos e ruínas antigas."],
};
